package cn.kaoyan.assistant;
import java.io.*;import java.util.*;import java.util.zip.*;import java.util.function.LongSupplier;
final class ArchiveIO {
 static final long MAX_TOTAL=10L*1024*1024*1024;static final int MAX_STATE=64*1024*1024;
 static void write(OutputStream output,byte[] state,Map<String,File> files)throws IOException{if(state.length>MAX_STATE||files.size()>20000)throw new IOException("备份记录或文件数量超过当前额度");long total=state.length;for(File file:files.values()){total+=file.length();if(file.length()>AttachmentTransfer.MAX_FILE_BYTES||total>MAX_TOTAL)throw new IOException("完整备份超过10GB，请分组备份");}try(ZipOutputStream z=new ZipOutputStream(new BufferedOutputStream(output))){z.putNextEntry(new ZipEntry("state.json"));z.write(state);z.closeEntry();byte[] b=new byte[65536];for(Map.Entry<String,File> e:files.entrySet()){validate("attachments/"+e.getKey());z.putNextEntry(new ZipEntry("attachments/"+e.getKey()));try(InputStream in=new FileInputStream(e.getValue())){int n;while((n=in.read(b))!=-1)z.write(b,0,n);}z.closeEntry();}}}
 static void validate(String path)throws IOException{if(!path.equals("state.json")&&!path.matches("attachments/[a-zA-Z0-9][a-zA-Z0-9._-]{0,99}"))throw new IOException("备份包含无效文件路径");}
 static byte[] stage(InputStream input,File directory,LongSupplier available)throws IOException{if(directory.exists()||!directory.mkdirs())throw new IOException("无法创建恢复暂存目录");Set<String> seen=new HashSet<>();long total=0;byte[] state=null,b=new byte[65536];try(ZipInputStream z=new ZipInputStream(new BufferedInputStream(input))){ZipEntry e;while((e=z.getNextEntry())!=null){String name=e.getName();validate(name);if(e.isDirectory()||!seen.add(name)||seen.size()>20001)throw new IOException("备份文件重复或数量过多");File f=new File(directory,name);if(!f.getCanonicalPath().startsWith(directory.getCanonicalPath()+File.separator))throw new IOException("备份路径无效");f.getParentFile().mkdirs();long count=0;try(OutputStream out=new FileOutputStream(f)){int n;while((n=z.read(b))!=-1){count+=n;total+=n;if(count>(name.equals("state.json")?MAX_STATE:AttachmentTransfer.MAX_FILE_BYTES)||total>MAX_TOTAL)throw new IOException("备份超过恢复容量");if(available.getAsLong()<AttachmentTransfer.RESERVE_BYTES)throw new IOException("空间不足，原记录未变更");out.write(b,0,n);}}z.closeEntry();if(name.equals("state.json")){try(InputStream in=new FileInputStream(f);ByteArrayOutputStream bytes=new ByteArrayOutputStream()){int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);state=bytes.toByteArray();}}}if(state==null)throw new IOException("备份缺少学习记录");return state;}catch(IOException e){remove(directory);throw e;}}
 static void remove(File file){if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)remove(child);}file.delete();}
}
